 5	public final class BucketSort {
 6	
 7	    private BucketSort() {
 8	    }
 9	
10	    public static void sort(float[] values) {
11	        if (values.length == 0) {
12	            return;
13	        }
14	
15	        List<List<Float>> buckets = createBuckets(values.length);
16	        distributeValues(values, buckets);
17	        sortBuckets(buckets);
18	        mergeBuckets(buckets, values);
19	    }
20	
21	    private static List<List<Float>> createBuckets(int bucketCount) {
22	        List<List<Float>> buckets = new ArrayList<>(bucketCount);
23	        for (int i = 0; i < bucketCount; i++) {
24	            buckets.add(new ArrayList<>());
25	        }
26	        return buckets;
27	    }
28	
29	    private static void distributeValues(float[] values, List<List<Float>> buckets) {
30	        int bucketCount = buckets.size();
31	        for (float value : values) {
32	            validateValue(value);
33	            int bucketIndex = (int) (bucketCount * value);
34	            buckets.get(bucketIndex).add(value);
35	        }
36	    }
37	
38	    private static void sortBuckets(List<List<Float>> buckets) {
39	        for (List<Float> bucket : buckets) {
40	            insertionSort(bucket);
41	        }
42	    }
43	
44	    private static void mergeBuckets(List<List<Float>> buckets, float[] values) {
45	        int index = 0;
46	        for (List<Float> bucket : buckets) {
47	            for (float value : bucket) {
48	                values[index++] = value;
49	            }
50	        }
51	    }
52	
53	    private static void insertionSort(List<Float> bucket) {
54	        for (int i = 1; i < bucket.size(); i++) {
55	            float currentValue = bucket.get(i);
56	            int j = i - 1;
57	            while (j >= 0 && bucket.get(j) > currentValue) {
58	                bucket.set(j + 1, bucket.get(j));
59	                j--;
60	            }
61	            bucket.set(j + 1, currentValue);
62	        }
63	    }
64	
65	    private static void validateValue(float value) {
66	        if (value < 0.0f || value >= 1.0f) {
67	            throw new IllegalArgumentException(
68	                "Bucket sort expects values in the range [0.0, 1.0): " + value
69	            );
70	        }
71	    }
